export function bindLive(name,acc){
 if(!K[name])throw new Error("late ports: unknown name "+name);
 if(Object.prototype.hasOwnProperty.call(G,name))throw new Error("late ports: duplicate binding "+name);
 G[name]=acc.get;if(acc.set)S[name]=acc.set;delete V[name]}
export function lateGet(name){
 if(!K[name])throw new Error("late ports: unknown name "+name);
 const g=G[name];return g?g():V[name]}
export function lateSet(name,v){
 if(!K[name])throw new Error("late ports: unknown name "+name);
 if(!Object.prototype.hasOwnProperty.call(G,name)){V[name]=v;return v}
 const s=S[name];if(!s)throw new TypeError("late ports: no setter for "+name);
 s(v);return v}
